if (root == nullptr) {
    root = new TreeNode(item);
} else {
    if (item < root->data) {
        avlInsert(root->left, item);
        if (bstHeight(root->left) - bstHeight(root->right) > 1) {
            if (item < root->left->data) {
                // Left-left case
                TreeNode<int>* newRoot = root->left;
                root->left = newRoot->right;
                newRoot->right = root;
                root->height = 1 + std::max(bstHeight(root->left), bstHeight(root->right));
                newRoot->height = 1 + std::max(bstHeight(newRoot->left), bstHeight(newRoot->right));
                root = newRoot;
            } else {
                // Left-right case
                avlRotateLeft(root->left);
                TreeNode<int>* newRoot = root->left;
                root->left = newRoot->right;
                newRoot->right = root;
                root->height = 1 + std::max(bstHeight(root->left), bstHeight(root->right));
                newRoot->height = 1 + std::max(bstHeight(newRoot->left), bstHeight(newRoot->right));
                root = newRoot;
            }
        }
    } else if (item > root->data) {
        avlInsert(root->right, item);
        if (bstHeight(root->right) - bstHeight(root->left) > 1) {
            if (item > root->right->data) {
                // Right-right case
                TreeNode<int>* newRoot = root->right;
                root->right = newRoot->left;
                newRoot->left = root;
                root->height = 1 + std::max(bstHeight(root->right), bstHeight(root->left));
                newRoot->height = 1 + std::max(bstHeight(newRoot->left), bstHeight(newRoot->right));
                root = newRoot;
            } else {
                // Right-left case
                avlRotateRight(root->right);
                TreeNode<int>* newRoot = root->right;
                root->right = newRoot->left;
                newRoot->left = root;
                root->height = 1 + std::max(bstHeight(root->right), bstHeight(root->left));
                newRoot->height = 1 + std::max(bstHeight(newRoot->left), bstHeight(newRoot->right));
                root = newRoot;
            }
        }
    }
}
root->height = 1 + std::max(bstHeight(root->left), bstHeight(root->right));

